// Hint: Assignment copies a struct but copies only a reference for a class.
// Practice: --practice 584; reference: --verify 584
static class E584 {
public struct CounterValue { public int Value; } public sealed class CounterObject { public int Value; }
 public static (int OriginalValue,int CopyValue,int SharedValue) Practice(int seed) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 584");
 }
 public static (int OriginalValue,int CopyValue,int SharedValue) Reference(int seed) {
  var original=new CounterValue { Value=seed };var copy=original;copy.Value=checked(copy.Value+1);var first=new CounterObject { Value=seed };var alias=first;alias.Value=checked(alias.Value+1);return (original.Value,copy.Value,first.Value);
 }
 private static (int OriginalValue,int CopyValue,int SharedValue) Solve(int seed) => Check.PracticeMode ? Practice(seed) : Reference(seed);
 public static void Verify() {
