// ======================================================================
// 628: Positional pattern geometry / scenario 1
// Use positional Point deconstruction. Origin gets origin; nonorigin Manhattan distance <=1 gets near; otherwise far. Avoid Math.Abs(int.MinValue) overflow.
// Hint: Cast coordinates to long before taking absolute values.
// Practice: --practice 628; reference: --verify 628
static class E628 {
public readonly record struct Point(int X,int Y);
 public static string Practice(Point point) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 628");
 }
 public static string Reference(Point point) {
  return point switch { (0,0)=>"origin", (var x,var y) when Math.Abs((long)x)+Math.Abs((long)y)<=1=>"near", _=>"far" };
 }
 private static string Solve(Point point) => Check.PracticeMode ? Practice(point) : Reference(point);
 public static void Verify() {
  Check.Equal("origin", Solve(new Point(0,0)));
  Check.Equal("near", Solve(new Point(-1,0)));
  Check.Equal("far", Solve(new Point(1,1)));
  Check.Equal("far", Solve(new Point(int.MinValue,0)));
 }
}

