// 639: List pattern packet classification / scenario 1
// Classify arrays using list patterns: empty; singleton 1 marker; two or more items starting 1 and ending 0 framed; other 1-prefixed packets open; all others foreign. Do not mutate.
// Hint: Order more specific list patterns before a broad prefix pattern.
// Practice: --practice 639; reference: --verify 639
static class E639 {

 public static string Practice(int[] packet) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 639");
 }
 public static string Reference(int[] packet) {
  return packet switch { []=>"empty", [1]=>"marker", [1,..,0]=>"framed", [1,..]=>"open", _=>"foreign" };
 }
 private static string Solve(int[] packet) => Check.PracticeMode ? Practice(packet) : Reference(packet);
 public static void Verify() {
  Check.Equal("empty", Solve(Array.Empty<int>()));
  Check.Equal("marker", Solve(new[] { 1 }));
  Check.Equal("framed", Solve(new[] { 1,7,0 }));
  Check.Equal("open", Solve(new[] { 1,3 }));
  Check.Equal("foreign", Solve(new[] { -1,0 }));
 }
}

