// ======================================================================
// 661: Nullable reference flow guards / scenario 1
// Safely navigate nullable Profile.Contact.Email. Missing/null/blank email returns missing. Trim present text; length below 1 returns short, otherwise return text unchanged in case. This is flow analysis, not email syntax validation.
// Hint: A successful is string pattern gives the compiler a non-null local.
// Practice: --practice 661; reference: --verify 661
static class E661 {
public sealed record Contact(string? Email); public sealed record Profile(Contact? Contact);
 public static string Practice(Profile? profile) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 661");
 }
 public static string Reference(Profile? profile) {
  if(profile?.Contact?.Email is not string email || string.IsNullOrWhiteSpace(email))return "missing";var trimmed=email.Trim();return trimmed.Length>=1?trimmed:"short";
 }
 private static string Solve(Profile? profile) => Check.PracticeMode ? Practice(profile) : Reference(profile);
 public static void Verify() {
  Check.Equal("missing", Solve(null));
  Check.Equal("missing", Solve(new Profile(null)));
  Check.Equal("missing", Solve(new Profile(new Contact(" "))));
  Check.Equal("A", Solve(new Profile(new Contact(" A "))));
  Check.Equal("missing", Solve(new Profile(new Contact(""))));
 }
}

