// 727: IComparable domain ordering / scenario 1
// Keep Candidate scores >=1, order through IComparable<Candidate> (descending score then ordinal ascending name), and return names. Null array elements are outside the contract.
// Hint: CompareTo must define a consistent ordering; avoid subtraction-based comparisons that overflow.
// Practice: --practice 727; reference: --verify 727
static class E727 {
public sealed record Candidate(string Name,int Score):IComparable<Candidate> { public int CompareTo(Candidate? other){if(other is null)return -1;int byScore=other.Score.CompareTo(Score);return byScore!=0?byScore:StringComparer.Ordinal.Compare(Name,other.Name);} }
 public static string[] Practice(Candidate[] values) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 727");
 }
 public static string[] Reference(Candidate[] values) {
  return values.Where(x=>x.Score>=1).Order().Select(x=>x.Name).ToArray();
 }
 private static string[] Solve(Candidate[] values) => Check.PracticeMode ? Practice(values) : Reference(values);
 public static void Verify() {
  Check.Equal(new string[] { "a", "b", "z" }, Solve(new[] { new Candidate("z",1),new Candidate("b",2),new Candidate("a",2) }));
  Check.Equal(new string[] {  }, Solve(new[] { new Candidate("x",0) }));
  Check.Equal(new string[] { "top" }, Solve(new[] { new Candidate("top",int.MaxValue) }));
 }
}

