// 749: Async running total producers / scenario 1
// Lazily produce running long totals seeded with 1. Yield once asynchronously per input, honoring cancellation before and after the yield. Read the input during enumeration, not factory construction.
// Hint: Async iterator Practice remains a non-async throwing factory until you implement yield return.
// Practice: --practice 749; reference: --verify 749
static class E749 {
private static async Task<long[]> Collect(IAsyncEnumerable<long> values){var result=new List<long>();await foreach(var item in values)result.Add(item);return result.ToArray();}
 public static IAsyncEnumerable<long> Practice(int[] values,CancellationToken cancellationToken=default) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 749");
 }
 public static async IAsyncEnumerable<long> Reference(int[] values,[EnumeratorCancellation] CancellationToken cancellationToken=default) {
  long total=1;foreach(var value in values){cancellationToken.ThrowIfCancellationRequested();await Task.Yield();cancellationToken.ThrowIfCancellationRequested();total+=value;yield return total;}
 }
 private static IAsyncEnumerable<long> Solve(int[] values,CancellationToken cancellationToken=default) => Check.PracticeMode ? Practice(values, cancellationToken) : Reference(values, cancellationToken);
 public static void Verify() {
  Check.Equal(new long[] { 2,0,3 }, Collect(Solve(new[] { 1,-2,3 })).GetAwaiter().GetResult());
  Check.Equal(Array.Empty<long>(), Collect(Solve(Array.Empty<int>())).GetAwaiter().GetResult());
  Check.Throws<OperationCanceledException>(() => { Collect(Solve(new[] { 1 },new CancellationToken(true))).GetAwaiter().GetResult(); });
  var input=new[] { 1 };var lazy=Solve(input);input[0]=4;Check.Equal(new long[] { 5 },Collect(lazy).GetAwaiter().GetResult());
 }
}

