// ======================================================================
// 760: Bounded channel drop-oldest policy / scenario 1
// Configure a bounded single-reader/single-writer Channel with capacity 1 and DropOldest. Write before draining; complete then return retained values oldest first. Unlike an unbounded channel, full writes discard the oldest item.
// Hint: DropOldest permits producer-first use without the deadlock that Wait mode would cause.
// Practice: --practice 760; reference: --verify 760
static class E760 {

 public static async Task<int[]> Practice(int[] values) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 760");
 }
 public static async Task<int[]> Reference(int[] values) {
  var channel=Channel.CreateBounded<int>(new BoundedChannelOptions(1) { SingleReader=true,SingleWriter=true,FullMode=BoundedChannelFullMode.DropOldest });foreach(var value in values)await channel.Writer.WriteAsync(value);channel.Writer.Complete();var result=new List<int>();await foreach(var value in channel.Reader.ReadAllAsync())result.Add(value);return result.ToArray();
 }
 private static Task<int[]> Solve(int[] values) => Check.PracticeMode ? Practice(values) : Reference(values);
 public static void Verify() {
  Check.Equal(new int[] { 3 }, Solve(Enumerable.Range(1,3).ToArray()).GetAwaiter().GetResult());
  Check.Equal(new int[] {  }, Solve(Array.Empty<int>()).GetAwaiter().GetResult());
  Check.Equal(new int[] { -1 }, Solve(new[] { -1 }).GetAwaiter().GetResult());
 }
}

