// 782: Task WhenAny winner observation / scenario 1
// Await the first completed task and add 1 checked. If multiple inputs are already complete, choose the first input (Task.WhenAny behavior). Await the winning task itself to observe its failure. Reject empty input. No cancellation of other tasks.
// Hint: WhenAny succeeds with a Task object even when the winning task faulted.
// Practice: --practice 782; reference: --verify 782
static class E782 {

 public static async Task<int> Practice(Task<int>[] operations) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 782");
 }
 public static async Task<int> Reference(Task<int>[] operations) {
  if(operations.Length==0)throw new ArgumentException("No contenders");var winner=await Task.WhenAny(operations).ConfigureAwait(false);return checked(await winner.ConfigureAwait(false)+1);
 }
 private static Task<int> Solve(Task<int>[] operations) => Check.PracticeMode ? Practice(operations) : Reference(operations);
 public static void Verify() {
  Check.Equal(8, Solve(new[] { Task.FromResult(7),Task.FromResult(2) }).GetAwaiter().GetResult());
  var pending=new TaskCompletionSource<int>();Check.Equal(4,Solve(new[] { pending.Task,Task.FromResult(3) }).GetAwaiter().GetResult());pending.SetResult(0);
  Check.Throws<InvalidOperationException>(() => { Solve(new[] { Task.FromException<int>(new InvalidOperationException()) }).GetAwaiter().GetResult(); });
  Check.Throws<ArgumentException>(() => { Solve(Array.Empty<Task<int>>()).GetAwaiter().GetResult(); });
 }
}

