// ======================================================================
// 793: Parallel ForEachAsync indexed mapping / scenario 1
// Use Parallel.ForEachAsync with maximum 1 workers. Map each input exactly once into its original index. Empty array returns []; reject null worker and propagate worker failure.
// Hint: Workers own distinct result indices, so completion order need not equal output order.
// Practice: --practice 793; reference: --verify 793
static class E793 {

 public static async Task<int[]> Practice(int[] values,Func<int,Task<int>> worker) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 793");
 }
 public static async Task<int[]> Reference(int[] values,Func<int,Task<int>> worker) {
  ArgumentNullException.ThrowIfNull(worker);var result=new int[values.Length];await Parallel.ForEachAsync(Enumerable.Range(0,values.Length),new ParallelOptions { MaxDegreeOfParallelism=1 },async (i,token)=>{result[i]=await worker(values[i]).ConfigureAwait(false);});return result;
 }
 private static Task<int[]> Solve(int[] values,Func<int,Task<int>> worker) => Check.PracticeMode ? Practice(values, worker) : Reference(values, worker);
 public static void Verify() {
  Check.Equal(new int[] { 6, 2, 6 }, Solve(new[] { 3,1,3 },x=>Task.FromResult(x*2)).GetAwaiter().GetResult());
  Check.Equal(new int[] {  }, Solve(Array.Empty<int>(),x=>Task.FromResult(x)).GetAwaiter().GetResult());
  int active=0,peak=0,calls=0;var mutex=new object();var result=Solve(Enumerable.Range(0,24).ToArray(),async x=>{lock(mutex){active++;calls++;peak=Math.Max(peak,active);}await Task.Yield();lock(mutex){active--;}return x;}).GetAwaiter().GetResult();Check.True(peak<=1);Check.Equal(24,calls);Check.Equal(Enumerable.Range(0,24).ToArray(),result);
  Check.Throws<InvalidOperationException>(() => { Solve(new[] { 1 },x=>Task.FromException<int>(new InvalidOperationException())).GetAwaiter().GetResult(); });
 }
}

