// ======================================================================
// 815: TimeProvider expiration boundaries / scenario 1
// An item expires exactly 1 minutes after created. Compare using injected TimeProvider.GetUtcNow; never read wall-clock time. Different offsets represent the same instant. Null clock throws.
// Hint: A frozen TimeProvider makes just-before and exact-boundary checks deterministic.
// Practice: --practice 815; reference: --verify 815
static class E815 {
private static readonly DateTimeOffset Epoch=new(2024,2,29,0,0,0,TimeSpan.Zero); public sealed class FrozenTime(DateTimeOffset now):TimeProvider { public override DateTimeOffset GetUtcNow()=>now; }
 public static bool Practice(DateTimeOffset created,TimeProvider clock) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 815");
 }
 public static bool Reference(DateTimeOffset created,TimeProvider clock) {
  ArgumentNullException.ThrowIfNull(clock);return clock.GetUtcNow()>=created.AddMinutes(1);
 }
 private static bool Solve(DateTimeOffset created,TimeProvider clock) => Check.PracticeMode ? Practice(created, clock) : Reference(created, clock);
 public static void Verify() {
  Check.Equal(false, Solve(Epoch,new FrozenTime(Epoch.AddMinutes(1).AddTicks(-1))));
  Check.Equal(true, Solve(Epoch,new FrozenTime(Epoch.AddMinutes(1))));
  Check.Equal(false, Solve(Epoch,new FrozenTime(Epoch.AddMinutes(-1))));
  Check.Equal(true, Solve(Epoch.ToOffset(TimeSpan.FromHours(3)),new FrozenTime(Epoch.AddMinutes(1))));
  Check.Throws<ArgumentNullException>(() => { Solve(Epoch,null!); });
 }
}

