// ======================================================================
// 903: BitOperations rotation and hexadecimal / scenario 1
// Rotate uint left 1 bits, return eight uppercase invariant hexadecimal digits and population count. Rotation wraps high bits, unlike a lossy shift.
// Hint: BitOperations makes width and circular movement explicit.
// Practice: --practice 903; reference: --verify 903
static class E903 {

 public static (string Hex,int Ones) Practice(uint value) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 903");
 }
 public static (string Hex,int Ones) Reference(uint value) {
  uint rotated=BitOperations.RotateLeft(value,1);return (rotated.ToString("X8",CultureInfo.InvariantCulture),BitOperations.PopCount(rotated));
 }
 private static (string Hex,int Ones) Solve(uint value) => Check.PracticeMode ? Practice(value) : Reference(value);
 public static void Verify() {
  Check.Equal(("00000002",1), Solve(1u));
  Check.Equal(("FFFFFFFF",32), Solve(uint.MaxValue));
  Check.Equal(("00000000",0), Solve(0u));
  Check.Equal(("00000001",1), Solve(0x80000000u));
 }
}

