// ======================================================================
// 925: Invariant TimeSpan scaling and formatting / scenario 1
// Parse constant-format TimeSpan (c), multiply ticks by 1 checked, and return invariant c format. Invalid input throws FormatException. Preserve subsecond precision; no floating-point conversion.
// Hint: Tick arithmetic avoids rounding fractional seconds.
// Practice: --practice 925; reference: --verify 925
static class E925 {

 public static string Practice(string duration) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 925");
 }
 public static string Reference(string duration) {
  if(!TimeSpan.TryParseExact(duration,"c",CultureInfo.InvariantCulture,out var parsed))throw new FormatException("Expected constant duration");return TimeSpan.FromTicks(checked(parsed.Ticks*1)).ToString("c",CultureInfo.InvariantCulture);
 }
 private static string Solve(string duration) => Check.PracticeMode ? Practice(duration) : Reference(duration);
 public static void Verify() {
  Check.Equal("00:00:01", Solve("00:00:01"));
  Check.Equal("00:00:00", Solve("00:00:00"));
  Check.Equal("-00:00:01", Solve("-00:00:01"));
  Check.Throws<FormatException>(() => { Solve("not-time"); });
 }
}

