  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 947");
 }
 public static DateTimeOffset Reference(DateTimeOffset instant,TimeZoneInfo zone) {
  ArgumentNullException.ThrowIfNull(zone);return TimeZoneInfo.ConvertTime(instant.AddMinutes(1),zone);
 }
 private static DateTimeOffset Solve(DateTimeOffset instant,TimeZoneInfo zone) => Check.PracticeMode ? Practice(instant, zone) : Reference(instant, zone);
 public static void Verify() {
  var zone=TimeZoneInfo.CreateCustomTimeZone("fixture",TimeSpan.FromHours(-5),"fixture","fixture");var instant=new DateTimeOffset(2024,2,29,23,59,0,TimeSpan.Zero);var result=Solve(instant,zone);Check.Equal(instant.AddMinutes(1),result);Check.Equal(TimeSpan.FromHours(-5),result.Offset);Check.Equal(new DateOnly(2024,2,29),DateOnly.FromDateTime(result.DateTime));
  Check.Throws<ArgumentNullException>(() => { Solve(DateTimeOffset.UnixEpoch,null!); });
 }
}

