  if(total<0||total*100m!=decimal.Truncate(total*100m))throw new ArgumentException("Nonnegative whole cents required");long cents=checked((long)(total*100m));long each=cents/1,remainder=cents%1;var result=new long[1];for(int i=0;i<result.Length;i++)result[i]=each+(i<remainder?1:0);return result;
