// 969: BigInteger modular exponentiation / scenario 1
// Compute value^exponent modulo 2 using BigInteger. Normalize negative bases into [0,modulus). Reject negative exponents; exponent zero returns 1 (including base zero).
// Hint: Normalize a negative remainder before calling modular exponentiation.
// Practice: --practice 969; reference: --verify 969
static class E969 {

 public static BigInteger Practice(BigInteger value,int exponent) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 969");
 }
 public static BigInteger Reference(BigInteger value,int exponent) {
  if(exponent<0)throw new ArgumentOutOfRangeException(nameof(exponent));BigInteger modulus=2;value=((value%modulus)+modulus)%modulus;return BigInteger.ModPow(value,exponent,modulus);
 }
 private static BigInteger Solve(BigInteger value,int exponent) => Check.PracticeMode ? Practice(value, exponent) : Reference(value, exponent);
 public static void Verify() {
  Check.Equal(new BigInteger(1), Solve(new BigInteger(3),5));
  Check.Equal(new BigInteger(1), Solve(new BigInteger(-1),2));
  Check.Equal(BigInteger.One, Solve(BigInteger.Zero,0));
  Check.Throws<ArgumentOutOfRangeException>(() => { Solve(BigInteger.One,-1); });
 }
}

