// ======================================================================
// 980: Deterministic topological dependency ordering / scenario 1
// Kahn topological sort of directed graph (source before target). Include leaf-only nodes; collapse duplicate edges; choose ready nodes with injected total comparer distinguishing unequal strings. Reject cycles. Related scenario has 1 independent prerequisites.
// Hint: Indegree must count the same distinct edges that the release step decrements.
// Practice: --practice 980; reference: --verify 980
static class E980 {

 public static string[] Practice(Dictionary<string,string[]> graph,IComparer<string> comparer) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 980");
 }
 public static string[] Reference(Dictionary<string,string[]> graph,IComparer<string> comparer) {
  var nodes=new HashSet<string>(graph.Keys,StringComparer.Ordinal);foreach(var edges in graph.Values)nodes.UnionWith(edges);var degree=nodes.ToDictionary(x=>x,_=>0,StringComparer.Ordinal);foreach(var edges in graph.Values)foreach(var next in edges.Distinct(StringComparer.Ordinal))degree[next]++;var ready=new SortedSet<string>(nodes.Where(x=>degree[x]==0),comparer);var result=new List<string>();while(ready.Count>0){var node=ready.Min!;ready.Remove(node);result.Add(node);foreach(var next in graph.GetValueOrDefault(node,Array.Empty<string>()).Distinct(StringComparer.Ordinal))if(--degree[next]==0)ready.Add(next);}if(result.Count!=nodes.Count)throw new InvalidOperationException("Cycle");return result.ToArray();
 }
 private static string[] Solve(Dictionary<string,string[]> graph,IComparer<string> comparer) => Check.PracticeMode ? Practice(graph, comparer) : Reference(graph, comparer);
 public static void Verify() {
  Check.Equal(new string[] { "a", "b", "c" }, Solve(new() { ["b"]=new[] { "c" },["a"]=new[] { "c","c" } },StringComparer.Ordinal));
  Check.Equal(new string[] { "b", "a", "c" }, Solve(new() { ["b"]=new[] { "c" },["a"]=new[] { "c" } },Comparer<string>.Create((a,b)=>StringComparer.Ordinal.Compare(b,a))));
  Check.Throws<InvalidOperationException>(() => { Solve(new() { ["a"]=new[] { "a" } },StringComparer.Ordinal); });
  Check.Equal(1, Solve(Enumerable.Range(0,1).ToDictionary(x=>x.ToString("D2",CultureInfo.InvariantCulture),_=>Array.Empty<string>()),StringComparer.Ordinal).Length);
  Check.Equal(new string[] {  }, Solve(new(),StringComparer.Ordinal));
 }
}

