  foreach(var edges in graph.Values)if(edges.Any(e=>e.Cost<0))throw new ArgumentException("Negative edge");var distance=new SortedDictionary<string,long>(StringComparer.Ordinal) { [start]=0 };var queue=new PriorityQueue<string,long>();queue.Enqueue(start,0);while(queue.TryDequeue(out var node,out var cost)){if(cost!=distance[node])continue;foreach(var edge in graph.GetValueOrDefault(node,Array.Empty<Edge>())){long candidate=checked(cost+edge.Cost+1);if(!distance.TryGetValue(edge.To,out var old)||candidate<old){distance[edge.To]=candidate;queue.Enqueue(edge.To,candidate);}}}return distance;
