// ======================================================================
// 1013: Trie prefix completion / scenario 1
// Build a char trie and return at most 1 distinct words beginning with prefix, sorted ordinally. Prefix itself may be a word; empty words and empty prefix are valid. Case-sensitive UTF-16 char ordering, no normalization.
// Hint: Terminal nodes distinguish a complete word from an internal prefix.
// Practice: --practice 1013; reference: --verify 1013
static class E1013 {
private sealed class TrieNode { public bool Terminal; public SortedDictionary<char,TrieNode> Children { get; }=new(); }
 public static string[] Practice(string[] words,string prefix) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1013");
 }
 public static string[] Reference(string[] words,string prefix) {
  var root=new TrieNode();foreach(var word in words){var node=root;foreach(char c in word){if(!node.Children.TryGetValue(c,out var next)){next=new TrieNode();node.Children[c]=next;}node=next;}node.Terminal=true;}var current=root;foreach(char c in prefix){if(!current.Children.TryGetValue(c,out var next))return Array.Empty<string>();current=next;}var result=new List<string>();void Visit(TrieNode node,string text){if(result.Count>=1)return;if(node.Terminal)result.Add(text);foreach(var pair in node.Children)Visit(pair.Value,text+pair.Key);}Visit(current,prefix);return result.ToArray();
 }
 private static string[] Solve(string[] words,string prefix) => Check.PracticeMode ? Practice(words, prefix) : Reference(words, prefix);
 public static void Verify() {
  Check.Equal(new string[] { "a" }, Solve(new[] { "ac","a","ab","a","b" },"a"));
  Check.Equal(new string[] {  }, Solve(new[] { "a" },"z"));
  Check.Equal(new string[] { "" }, Solve(new[] { "x","" },""));
  Check.Equal(new string[] {  }, Solve(Array.Empty<string>(),""));
 }
}

