// ======================================================================
// 1024: LRU access order with eviction callbacks / scenario 1
// Simulate an LRU cache of capacity 1. Every access inserts or promotes a key. On insertion at capacity evict least recent and call injected callback once. Return least-to-most-recent keys. Repeated keys do not consume capacity or trigger eviction.
// Hint: A dictionary plus linked list supports O(1) promotion and eviction.
// Practice: --practice 1024; reference: --verify 1024
static class E1024 {

 public static string[] Practice(string[] accesses,Action<string> evict) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1024");
 }
 public static string[] Reference(string[] accesses,Action<string> evict) {
  ArgumentNullException.ThrowIfNull(evict);var order=new LinkedList<string>();var nodes=new Dictionary<string,LinkedListNode<string>>(StringComparer.Ordinal);foreach(var key in accesses){if(nodes.Remove(key,out var existing))order.Remove(existing);else if(order.Count==1){string old=order.First!.Value;order.RemoveFirst();nodes.Remove(old);evict(old);}nodes[key]=order.AddLast(key);}return order.ToArray();
 }
 private static string[] Solve(string[] accesses,Action<string> evict) => Check.PracticeMode ? Practice(accesses, evict) : Reference(accesses, evict);
 public static void Verify() {
  var removed=new List<string>();var keys=Enumerable.Range(0,2).Select(x=>"k"+x.ToString(CultureInfo.InvariantCulture)).ToArray();Check.Equal(keys.Skip(1).ToArray(),Solve(keys,removed.Add));Check.Equal(new[] { "k0" },removed.ToArray());
  Check.Equal(new string[] { "x" }, Solve(new[] { "x","x" },_=>throw new Exception("Unexpected eviction")));
  Check.Equal(new string[] {  }, Solve(Array.Empty<string>(),_=>{}));
  var promoted=Solve(new[] { "a","b","a" },_=>{});Check.Equal(new[] { "a" },promoted);
 }
}

