// ======================================================================
// 1035: Disjoint-set union components / scenario 1
// Union undirected edges over vertices 0..1; return each vertex's smallest component member as canonical root. Use path compression, handle duplicate/self edges, reject out-of-range vertices.
// Hint: Link larger roots beneath smaller roots to preserve the canonical-minimum invariant.
// Practice: --practice 1035; reference: --verify 1035
static class E1035 {

 public static int[] Practice((int Left,int Right)[] edges) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1035");
 }
 public static int[] Reference((int Left,int Right)[] edges) {
  var parent=Enumerable.Range(0,2).ToArray();int Find(int x){while(parent[x]!=x){parent[x]=parent[parent[x]];x=parent[x];}return x;}foreach(var (left,right) in edges){if(left<0||left>=2||right<0||right>=2)throw new ArgumentOutOfRangeException(nameof(edges));int a=Find(left),b=Find(right);if(a!=b)parent[Math.Max(a,b)]=Math.Min(a,b);}return Enumerable.Range(0,2).Select(Find).ToArray();
 }
 private static int[] Solve((int Left,int Right)[] edges) => Check.PracticeMode ? Practice(edges) : Reference(edges);
 public static void Verify() {
  Check.Equal(new int[] { 0, 0 }, Solve(new[] { (1,0),(0,1),(1,1) }));
  Check.Equal(new int[] { 0, 1 }, Solve(Array.Empty<(int,int)>()));
  Check.Equal(new int[2], Solve(Enumerable.Range(1,1).Select(i=>(i-1,i)).ToArray()));
  Check.Throws<ArgumentOutOfRangeException>(() => { Solve(new[] { (0,2) }); });
 }
}

