// 1068: Spiral rectangular matrix traversal / scenario 1
// Traverse a rectangular matrix clockwise from top-left in a spiral. Return every element once without mutation. Scenario includes a 1-column strip plus odd-center and empty boundaries.
// Hint: Recheck bounds after each side to avoid duplicating a final row or column.
// Practice: --practice 1068; reference: --verify 1068
static class E1068 {

 public static int[] Practice(int[,] matrix) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1068");
 }
 public static int[] Reference(int[,] matrix) {
  int top=0,bottom=matrix.GetLength(0)-1,left=0,right=matrix.GetLength(1)-1;var result=new List<int>();while(top<=bottom&&left<=right){for(int c=left;c<=right;c++)result.Add(matrix[top,c]);top++;for(int r=top;r<=bottom;r++)result.Add(matrix[r,right]);right--;if(top<=bottom){for(int c=right;c>=left;c--)result.Add(matrix[bottom,c]);bottom--;}if(left<=right){for(int r=bottom;r>=top;r--)result.Add(matrix[r,left]);left++;}}return result.ToArray();
 }
 private static int[] Solve(int[,] matrix) => Check.PracticeMode ? Practice(matrix) : Reference(matrix);
 public static void Verify() {
  Check.Equal(new int[] { 1, 2, 3, 6, 9, 8, 7, 4, 5 }, Solve(new[,] { {1,2,3},{4,5,6},{7,8,9} }));
  var strip=new int[1,1];for(int i=0;i<1;i++)strip[0,i]=i;Check.Equal(Enumerable.Range(0,1).ToArray(),Solve(strip));
  Check.Equal(new int[] {  }, Solve(new int[0,3]));
  Check.Equal(new int[] { 1, 2, 3 }, Solve(new[,] { {1},{2},{3} }));
 }
}

