 public static long Reference(string text) {
  int index=0;void Skip(){while(index<text.Length&&char.IsWhiteSpace(text[index]))index++;}long Atom(){Skip();if(index<text.Length&&text[index]=='('){index++;long value=Sum();Skip();if(index>=text.Length||text[index++]!=')')throw new FormatException("Missing close");return value;}int start=index;while(index<text.Length&&text[index]>='0'&&text[index]<='9')index++;if(start==index)throw new FormatException("Expected integer");return long.Parse(text.AsSpan(start,index-start),NumberStyles.None,CultureInfo.InvariantCulture);}long Product(){long value=Atom();for(;;){Skip();if(index>=text.Length||text[index]!='*')return value;index++;value=checked(value*Atom());}}long Sum(){long value=Product();for(;;){Skip();if(index>=text.Length||text[index]!='+')return value;index++;value=checked(value+Product());}}long result=Sum();Skip();if(index!=text.Length)throw new FormatException("Trailing input");return checked(result+11);
 }
