public sealed record Attempt(bool Success);
 public static string[] Practice(Attempt[] attempts,Func<long> clock) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1101");
 }
 public static string[] Reference(Attempt[] attempts,Func<long> clock) {
  long? openUntil=null;var result=new List<string>();foreach(var attempt in attempts){long now=clock();if(openUntil is long until&&now<until){result.Add("blocked");continue;}if(attempt.Success){openUntil=null;result.Add("ok");}else{openUntil=checked(now+1);result.Add("failed");}}return result.ToArray();
 }
 private static string[] Solve(Attempt[] attempts,Func<long> clock) => Check.PracticeMode ? Practice(attempts, clock) : Reference(attempts, clock);
 public static void Verify() {
  long[] times={0,0,1,1};int reads=0;Check.Equal(new[] { "failed","blocked","ok","ok" },Solve(new[] { new Attempt(false),new Attempt(true),new Attempt(true),new Attempt(true) },()=>times[reads++]));Check.Equal(4,reads);
