// ======================================================================
// 1112: Unit-of-work atomic staged transfers / scenario 1
// Transfer amount from Left to Right with fee 1 removed from Left. Read injected store once; insufficient funds returns false without commit. Validate and compute both new balances before one atomic Commit. Negative amounts throw; overflow must not partially commit.
// Hint: A unit of work stages all derived values before crossing the commit boundary.
// Practice: --practice 1112; reference: --verify 1112
static class E1112 {
public interface IStore { (long Left,long Right) Read(); void Commit(long left,long right); } public sealed class MemoryStore(long left,long right):IStore { public long Left=left,Right=right; public int Commits; public (long Left,long Right) Read()=>(Left,Right); public void Commit(long left,long right){Left=left;Right=right;Commits++;} }
 public static bool Practice(IStore store,int amount) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1112");
 }
 public static bool Reference(IStore store,int amount) {
  if(amount<0)throw new ArgumentOutOfRangeException(nameof(amount));var state=store.Read();if(state.Left<amount+1L)return false;long left=checked(state.Left-amount-1);long right=checked(state.Right+amount);store.Commit(left,right);return true;
 }
 private static bool Solve(IStore store,int amount) => Check.PracticeMode ? Practice(store, amount) : Reference(store, amount);
 public static void Verify() {
  var store=new MemoryStore(100,10);Check.True(Solve(store,20));Check.Equal(79L,store.Left);Check.Equal(30L,store.Right);Check.Equal(1,store.Commits);
  var poor=new MemoryStore(0,0);Check.Equal(false,Solve(poor,0));Check.Equal(0,poor.Commits);
  var overflow=new MemoryStore(100,long.MaxValue);Check.Throws<OverflowException>(()=>Solve(overflow,1));Check.Equal(100L,overflow.Left);Check.Equal(0,overflow.Commits);
  Check.Throws<ArgumentOutOfRangeException>(() => { Solve(new MemoryStore(0,0),-1); });
 }
}

