// ======================================================================
// 1123: Repository optimistic version updates / scenario 1
// Update repository row ID 1 only at expectedVersion. Missing/stale returns false. Create a new Row with incremented version and new value, then use atomic TryReplace so a race after Get cannot overwrite newer state. Null value throws.
// Hint: The early version check is not enough; the write must compare the version again.
// Practice: --practice 1123; reference: --verify 1123
static class E1123 {
public sealed record Row(int Version,string Value); public interface IRepository { Row? Get(int id); bool TryReplace(int id,int expected,Row replacement); } public sealed class MemoryRepository(int id,Row? initial):IRepository { public Row? Current=initial; public bool RejectWrite; public Row? Get(int key)=>key==id?Current:null; public bool TryReplace(int key,int expected,Row replacement){if(RejectWrite||key!=id||Current?.Version!=expected)return false;Current=replacement;return true;} }
 public static bool Practice(IRepository repository,int expectedVersion,string value) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1123");
 }
 public static bool Reference(IRepository repository,int expectedVersion,string value) {
  ArgumentNullException.ThrowIfNull(value);var row=repository.Get(1);if(row is null||row.Version!=expectedVersion)return false;return repository.TryReplace(1,expectedVersion,row with { Value=value,Version=checked(expectedVersion+1) });
 }
 private static bool Solve(IRepository repository,int expectedVersion,string value) => Check.PracticeMode ? Practice(repository, expectedVersion, value) : Reference(repository, expectedVersion, value);
 public static void Verify() {
  var repo=new MemoryRepository(1,new Row(2,"old"));Check.True(Solve(repo,2,"new"));Check.Equal(new Row(3,"new"),repo.Current);Check.Equal(false,Solve(repo,2,"stale"));Check.Equal("new",repo.Current!.Value);
  Check.Equal(false,Solve(new MemoryRepository(2,new Row(1,"x")),1,"y"));
  var race=new MemoryRepository(1,new Row(1,"old")) { RejectWrite=true };Check.Equal(false,Solve(race,1,"new"));Check.Equal("old",race.Current!.Value);
  Check.Throws<ArgumentNullException>(() => { Solve(new MemoryRepository(1,null),1,null!); });
 }
}

