// 1145: Sieve smallest-prime-factor tables / scenario 1
// Build smallest-prime-factor table for indices 0..limit, accepting 0<=limit<=10. Entries 0 and 1 stay 0, primes map to themselves, composites map to smallest prime. Use a sieve rather than testing each number independently.
// Hint: Only the first prime marking a composite is its smallest factor.
// Practice: --practice 1145; reference: --verify 1145
static class E1145 {

 public static int[] Practice(int limit) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1145");
 }
 public static int[] Reference(int limit) {
  if(limit<0||limit>10)throw new ArgumentOutOfRangeException(nameof(limit));var result=new int[limit+1];for(int p=2;p<=limit;p++){if(result[p]!=0)continue;result[p]=p;if((long)p*p>limit)continue;for(int multiple=p*p;multiple<=limit;multiple+=p)if(result[multiple]==0)result[multiple]=p;}return result;
 }
 private static int[] Solve(int limit) => Check.PracticeMode ? Practice(limit) : Reference(limit);
 public static void Verify() {
  Check.Equal(new int[] { 0 }, Solve(0));
  Check.Equal(new int[] { 0, 0, 2, 3, 2, 5, 2, 7, 2, 3, 2 }, Solve(10));
  Check.Equal(new int[] { 0, 0, 2, 3, 2, 5, 2, 7, 2, 3, 2 }, Solve(10));
  Check.Throws<ArgumentOutOfRangeException>(() => { Solve(11); });
  Check.Throws<ArgumentOutOfRangeException>(() => { Solve(-1); });
 }
}

