// ======================================================================
// 1156: Markdown-lite block parsing / scenario 1
// Parse up to 1 nonblank line blocks. Recognize 1..1 leading # characters followed by a space as hLEVEL, otherwise p. Trim content, preserve literal markup (no HTML rendering). CRLF, CR and LF line endings work. This is explicitly a Markdown subset, not CommonMark.
// Hint: StringReader handles platform-independent line endings; heading syntax requires a separating space.
// Practice: --practice 1156; reference: --verify 1156
static class E1156 {
public sealed record Block(string Kind,string Text);
 public static Block[] Practice(string text) {
  // TODO: implement the exercise without calling Reference.
  throw new NotImplementedException("Exercise 1156");
 }
 public static Block[] Reference(string text) {
  using var reader=new StringReader(text);var result=new List<Block>();string? line;while((line=reader.ReadLine()) is not null){if(string.IsNullOrWhiteSpace(line))continue;int hashes=0;while(hashes<line.Length&&line[hashes]=='#')hashes++;if(hashes>=1&&hashes<=1&&hashes<line.Length&&line[hashes]==' ')result.Add(new Block("h"+hashes.ToString(CultureInfo.InvariantCulture),line[(hashes+1)..].Trim()));else result.Add(new Block("p",line.Trim()));if(result.Count==1)break;}return result.ToArray();
 }
 private static Block[] Solve(string text) => Check.PracticeMode ? Practice(text) : Reference(text);
 public static void Verify() {
  Check.Equal(new[] { new Block("h1","Title") }, Solve("# Title\r\n"));
  Check.Equal(new[] { new Block("p","#NoSpace") }, Solve("#NoSpace"));
  Check.Equal(Array.Empty<Block>(), Solve(" \r\n\n\r"));
  Check.Equal(new Block[] { new Block("p","x") }, Solve(string.Join("\r",Enumerable.Repeat("x",3))));
 }
}

